package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Client { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=100) private String name; @NotBlank @Pattern(regexp="[+0-9() -]{7,20}") private String phone; @Email @Size(max=120) private String email; public Client(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} }
